// 1. TCC示例 - 订单扣库存
// Try: 冻结库存
@Service
public class InventoryTccService {
    @Transactional
    public boolean tryDeduct(String skuId, int quantity) {
        // 检查可用库存
        Inventory inv = inventoryRepo.selectForUpdate(skuId);
        if (inv.getAvailable() < quantity) return false;
        // 冻结库存
        inv.setAvailable(inv.getAvailable() - quantity);
        inv.setFrozen(inv.getFrozen() + quantity);
        inventoryRepo.update(inv);
        return true;
    }

    // Confirm: 扣减冻结库存
    @Transactional
    public void confirmDeduct(String skuId, int quantity) {
        Inventory inv = inventoryRepo.findBySkuId(skuId);
        inv.setFrozen(inv.getFrozen() - quantity);
        inventoryRepo.update(inv);
    }

    // Cancel: 解冻库存
    @Transactional
    public void cancelDeduct(String skuId, int quantity) {
        Inventory inv = inventoryRepo.findBySkuId(skuId);
        inv.setFrozen(inv.getFrozen() - quantity);
        inv.setAvailable(inv.getAvailable() + quantity);
        inventoryRepo.update(inv);
    }
}

// 2. 本地消息表
@Service
public class OrderService {
    @Transactional
    public OrderId createOrder(CreateOrderCmd cmd) {
        // 1. 创建订单
        Order order = Order.create(cmd);
        orderRepo.save(order);

        // 2. 写本地消息表（同一个事务）
        LocalMessage msg = new LocalMessage();
        msg.setTopic("order-created");
        msg.setPayload(JSON.toJSONString(order));
        msg.setStatus(MessageStatus.PENDING);
        localMessageRepo.save(msg);

        return order.getId();
    }
}

// 后台任务轮询发送
@Scheduled(fixedDelay = 1000)
public void pollAndSend() {
    List<LocalMessage> messages = localMessageRepo
        .findByStatus(MessageStatus.PENDING, 100);
    for (LocalMessage msg : messages) {
        try {
            kafkaTemplate.send(msg.getTopic(), msg.getPayload());
            msg.setStatus(MessageStatus.SENT);
            localMessageRepo.update(msg);
        } catch (Exception e) {
            msg.setRetryCount(msg.getRetryCount() + 1);
            localMessageRepo.update(msg);
        }
    }
}

// 3. Seata AT模式
@GlobalTransactional(timeoutMills = 60000, name = "create-order")
public OrderId createOrder(CreateOrderCmd cmd) {
    // 本地操作
    Order order = Order.create(cmd);
    orderRepo.save(order);
    // 远程调用（Seata自动管理分布式事务）
    inventoryClient.deduct(cmd.getItems());
    return order.getId();
}
